INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nfhj804','남극해 관련 국제사회에서 해양외교 노력 결실! 국제규범 제안 채택에 이어 새 어장 개척도 성공','우리나라가 제안한 2건의 국제규범이 남극해양생물자원보존위원회(CCAMLR) 연례 회의에서 채택되었다. 또한 우리측의 과학 조사를 근거로 남극해 ''88.3 해구''의 새 어장이 개척되어 이빨고기 조업 재개의 길이 열렸다.','우리나라가 제안한 2건의 국제규범이 남극해양생물자원보존위원회(CCAMLR) 연례 회의에서 채택되었다. 또한 우리측의 과학 조사를 근거로 남극해 ''88.3 해구''의 새 어장이 개척되어 이빨고기 조업 재개의 길이 열렸다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787891','2026-11-04',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787891') AND NOT EXISTS (SELECT 1 FROM news WHERE id='nfhj804');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'ngncedd','(동정) 남재헌 해수부 차관, 부산국제수산엑스포에서 수산식품 수출 현장 점검','남재헌 해양수산부 차관이 ''제24회 부산국제수산엑스포'' 개막식에 참석하고 해외 바이어 초청 수산식품 수출 무역상담회를 점검했다. 남 차관은 수출 기업들을 격려하며 고부가가치 상품 개발과 해외 시장 개척 등을 통해 수산식품 수출을 든든히 뒷받침하겠다고 밝혔다.','남재헌 해양수산부 차관이 ''제24회 부산국제수산엑스포'' 개막식에 참석하고 해외 바이어 초청 수산식품 수출 무역상담회를 점검했다. 남 차관은 수출 기업들을 격려하며 고부가가치 상품 개발과 해외 시장 개척 등을 통해 수산식품 수출을 든든히 뒷받침하겠다고 밝혔다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787964','2026-11-04',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787964') AND NOT EXISTS (SELECT 1 FROM news WHERE id='ngncedd');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'ni0wvjd','해수부-경제협력개발기구-한국해양수산개발원, 세계해양포럼에서 해양경제를 논한다','해양수산부는 OECD 및 한국해양수산개발원과 함께 부산에서 세계와 한국의 해양경제를 주제로 국제 세미나를 개최한다. 이번 행사에서 국내 해양수산업의 총산출액은 약 197.7조 원, 부가가치는 약 63.2조 원 등으로 발표되었다.','해양수산부는 OECD 및 한국해양수산개발원과 함께 부산에서 세계와 한국의 해양경제를 주제로 국제 세미나를 개최한다. 이번 행사에서 국내 해양수산업의 총산출액은 약 197.7조 원, 부가가치는 약 63.2조 원 등으로 발표되었다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787890','2026-11-04',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787890') AND NOT EXISTS (SELECT 1 FROM news WHERE id='ni0wvjd');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nwmk9yy','세계 해양의 혁신 기술, ''오션테크코리아''에서 국내 기업과 연결된다','해양수산부는 해외 혁신기업의 기술과 사업 모델을 소개하고 국내 기업과의 비즈니스 미팅을 지원하는 ''오션테크코리아''를 개최한다. 이번 행사를 통해 국내 해양수산기업들이 세계 시장을 선제적으로 개척하고 수출 성과를 창출할 수 있도록 도울 예정이다.','해양수산부는 해외 혁신기업의 기술과 사업 모델을 소개하고 국내 기업과의 비즈니스 미팅을 지원하는 ''오션테크코리아''를 개최한다. 이번 행사를 통해 국내 해양수산기업들이 세계 시장을 선제적으로 개척하고 수출 성과를 창출할 수 있도록 도울 예정이다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787892','2026-11-04',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/briefing/pressReleaseView.do?newsId=156787892') AND NOT EXISTS (SELECT 1 FROM news WHERE id='nwmk9yy');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'n92avpz','수과원, 개체굴 선진 양식기술서 국문판 발간','국립수산과학원은 개체굴 양식기술의 국내 확산과 산업 경쟁력 강화를 위해 국제 선진 양식기술을 담은 「개체굴 양식기술 기초지식」 국문판을 발간했다. 이 책자는 종자생산부터 양성시설 및 관리 등 실용 기술을 담았으며, 관련 워크숍에서 처음 공개되어 무료로 배포될 예정이다.','국립수산과학원은 개체굴 양식기술의 국내 확산과 산업 경쟁력 강화를 위해 국제 선진 양식기술을 담은 「개체굴 양식기술 기초지식」 국문판을 발간했다. 이 책자는 종자생산부터 양성시설 및 관리 등 실용 기술을 담았으며, 관련 워크숍에서 처음 공개되어 무료로 배포될 예정이다.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4927&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-03',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4927&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1') AND NOT EXISTS (SELECT 1 FROM news WHERE id='n92avpz');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nvgsq2d','수과원, 서해 먼바다 멸치 어장 이용 가능성 확인','국립수산과학원은 서해 황해저층냉수해역에서 멸치 어군이 강하게 형성되어 새로운 어장으로 이용될 가능성이 높다고 밝혔다. 융합탐지기술을 통한 조사 결과, 저층냉수대역 주변에서 멸치의 어획 비중과 어군 밀도가 크게 증가한 것으로 확인됐다.','국립수산과학원은 서해 황해저층냉수해역에서 멸치 어군이 강하게 형성되어 새로운 어장으로 이용될 가능성이 높다고 밝혔다. 융합탐지기술을 통한 조사 결과, 저층냉수대역 주변에서 멸치의 어획 비중과 어군 밀도가 크게 증가한 것으로 확인됐다.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4929&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-03',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4929&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1') AND NOT EXISTS (SELECT 1 FROM news WHERE id='nvgsq2d');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'n_ko_156782514','고수온 피해 양식 어가에 1차 재난 지원금','해양수산부는 추석 명절 전 고수온 피해를 입은 338개 어가를 대상으로 재난 지원금 137억 원을 신속히 지원한다. 아울러 피해 어가를 위한 대출 상환 연기 및 이자 감면 등 간접 지원도 함께 추진한다.','해양수산부는 추석 명절 전 고수온 피해를 입은 338개 어가를 대상으로 재난 지원금 137억 원을 신속히 지원한다. 아울러 피해 어가를 위한 대출 상환 연기 및 이자 감면 등 간접 지원도 함께 추진한다.','해양수산부 / 정책브리핑','https://www.korea.kr/briefing/pressReleaseView.do?newsId=156782514','2026-09-20',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/briefing/pressReleaseView.do?newsId=156782514') AND NOT EXISTS (SELECT 1 FROM news WHERE id='n_ko_156782514');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'n_ko_148965977','한국의 갯벌, 세계유산 확대 등재 권고','국제자연보전연맹은 한국의 갯벌 세계유산 범위를 여수·고흥·무안·서산 갯벌까지 확대할 것을 권고했습니다. 2026년 6월 발표 당시 최종 결정은 세계유산위원회에 예정돼 있었습니다. 원문의 텍스트는 공공누리 제1유형입니다.','국제자연보전연맹은 한국의 갯벌 세계유산 범위를 여수·고흥·무안·서산 갯벌까지 확대할 것을 권고했습니다. 2026년 6월 발표 당시 최종 결정은 세계유산위원회에 예정돼 있었습니다. 원문의 텍스트는 공공누리 제1유형입니다.','국가유산청·해양수산부 / 정책브리핑','https://www.korea.kr/news/policyNewsView.do?newsId=148965977','2026-06-05',0,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.korea.kr/news/policyNewsView.do?newsId=148965977') AND NOT EXISTS (SELECT 1 FROM news WHERE id='n_ko_148965977');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'njmkcni','수산생명자원, 국가중요과학기술자료 등록으로 중요성 인정받아','100여 년 전에 한반도 북부에서 채집된 물고기 표본 148점이 국가중요과학기술자료로 등록되었어요. 이 표본에는 멸종 위기 종과 한반도 최북단 서식 종 등이 포함되어 있어 학술적 가치가 매우 높아요. 기후변화 이전의 수생태계 모습을 보여주는 이 소중한 자료는 앞으로 안전하게 보존될 예정이에요.','100여 년 전에 한반도 북부에서 채집된 물고기 표본 148점이 국가중요과학기술자료로 등록되었어요. 이 표본에는 멸종 위기 종과 한반도 최북단 서식 종 등이 포함되어 있어 학술적 가치가 매우 높아요. 기후변화 이전의 수생태계 모습을 보여주는 이 소중한 자료는 앞으로 안전하게 보존될 예정이에요.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4941&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-11',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4941&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1') AND NOT EXISTS (SELECT 1 FROM news WHERE id='njmkcni');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nkpe42p','수과원, 한국수산과학회 학회상 4개 부문 수상','국립수산과학원이 6일 한국수산과학회 총회에서 수산과학 분야 발전과 기술혁신에 기여한 공로로 학회상 4개 부문을 수상했어요. 목종수 부장, 민병화 과장, 이미경 연구사, 주희태 연구사가 각각 학술상과 기술혁신상 등을 받는 영예를 안았답니다. 수과원은 앞으로도 현장에 꼭 필요한 연구와 혁신적인 기술을 개발해 지속 가능한 해양수산업 발전에 기여하겠다고 밝혔어요.','국립수산과학원이 6일 한국수산과학회 총회에서 수산과학 분야 발전과 기술혁신에 기여한 공로로 학회상 4개 부문을 수상했어요. 목종수 부장, 민병화 과장, 이미경 연구사, 주희태 연구사가 각각 학술상과 기술혁신상 등을 받는 영예를 안았답니다. 수과원은 앞으로도 현장에 꼭 필요한 연구와 혁신적인 기술을 개발해 지속 가능한 해양수산업 발전에 기여하겠다고 밝혔어요.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4935&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-11-10',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4935&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1') AND NOT EXISTS (SELECT 1 FROM news WHERE id='nkpe42p');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nakm1ok','수과원, 수산생물 육종기술 고도화를 위한 미래전략 모색','국립수산과학원은 최근 기후변화로 어려움을 겪는 양식 어업을 위해 수산·축산 전문가들이 모여 우량품종 개발 방안을 논의했어요.

축산 분야의 발달한 육종기술을 수산생물에 맞게 활용하는 방법을 나누며, 성장이 빠르고 고수온·질병에 강한 품종을 만들기 위해 협력하기로 했답니다.','국립수산과학원은 최근 기후변화로 어려움을 겪는 양식 어업을 위해 수산·축산 전문가들이 모여 우량품종 개발 방안을 논의했어요.

