INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'n0qaao7','남극해 관련 국제사회에서 해양외교 노력 결실! 국제규범 제안 채택에 이어 새 어장 개척도 성공','우리나라가 제안한 남극해 보호 규범 2건이 국제회의에서 채택되고, 남극 바다에 새로운 이빨고기(메로) 어장이 열렸어요.

