INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nvscgqe','전국 연안 산소부족 물덩어리 완전 소멸','올해 5월부터 나타났던 ''산소부족 물덩어리''가 29일 진해만을 끝으로 완전히 사라졌어요.

