INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nrt1tmy','수과원, 활수산물 장거리 해상 운송 안정화로 수출길 넓힌다','국립수산과학원이 활수산물을 멀리 수송할 때 생존율을 높이고 신선도를 유지하는 암모니아 저감 장치를 개발했어요.

