INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nbw1l2j','수과원, 벤자리 양식산업화 육성 기반 마련','국립수산과학원은 고수온에 강한 새로운 양식 품종인 벤자리를 널리 알리고 산업화하기 위해 ‘벤자리 양식산업화 협의체’를 구성했어요.

