INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'nrkp5em','기후위기의 동해, 수산업 미래를 함께 찾는다','국립수산과학원은 17일 강릉에서 기후위기에 따른 동해안 수산업의 위기를 극복하고 협력 방안을 논의하기 위한 ‘2026 동해 수산 미래 심포지엄’을 개최해요. 이번 행사는 기조 강연과 주제발표, 종합토론을 통해 동해의 아열대화 대응, 수산자원 변동, 양식품종 연구개발 등을 다룰 예정이에요. 수과원은 현장 중심의 연구와 정책 지원으로 동해안 수산업의 지속 가능한 발전을 뒷받침하겠다고 밝혔어요.','국립수산과학원은 17일 강릉에서 기후위기에 따른 동해안 수산업의 위기를 극복하고 협력 방안을 논의하기 위한 ‘2026 동해 수산 미래 심포지엄’을 개최해요. 이번 행사는 기조 강연과 주제발표, 종합토론을 통해 동해의 아열대화 대응, 수산자원 변동, 양식품종 연구개발 등을 다룰 예정이에요. 수과원은 현장 중심의 연구와 정책 지원으로 동해안 수산업의 지속 가능한 발전을 뒷받침하겠다고 밝혔어요.','국립수산과학원 / 보도자료','https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4909&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1','2026-09-16',1,1,'2026-11-11T00:00:00+09:00' WHERE NOT EXISTS (SELECT 1 FROM news WHERE url='https://www.nifs.go.kr/news/actionNewsView.do?MENU_ID=M0000307&NEWS_SEQ=4909&NEWS_D_DATE_BEGIN=2020-01-01&NEWS_D_DATE_END=2030-12-31&PARENT_NEWS_HG_CODE=&NEWS_D_SUBJECT=&selectPage=1') AND NOT EXISTS (SELECT 1 FROM news WHERE id='nrkp5em');
INSERT INTO news (id,title,summary,body,source,url,date,ai,public,created_at) SELECT 'n02si9b','수과원-나가사키대학, 수산과학 공동연구 본격화','국립수산과학원이 부산에서 일본 나가사키대학과 함께 기후변화 시대의 수산업 발전을 위한 공동연구 세미나를 개최했어요.

